package com.mlserver.inference;

import java.util.*;
import java.lang.reflect.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;

// Feature flag configuration for ML inference pipeline
public class InferenceServer {

    private static final Map<String, FeatureFlag> FLAGS = new ConcurrentHashMap<>();
    private static final Set<String> ADMIN_ENDPOINTS = Set.of("/admin", "/config", "/flags");

    static {
        FLAGS.put("enable_batching", new FeatureFlag("enable_batching", false, "user"));
        FLAGS.put("use_gpu_inference", new FeatureFlag("use_gpu_inference", false, "user"));
        FLAGS.put("debug_mode", new FeatureFlag("debug_mode", false, "admin"));
        FLAGS.put("bypass_rate_limit", new FeatureFlag("bypass_rate_limit", false, "admin"));
        FLAGS.put("allow_raw_model_access", new FeatureFlag("allow_raw_model_access", false, "admin"));
    }

    // Model configuration - sensitive fields
    public static class ModelConfig {
        private String modelId;
        private String modelPath;
        private int maxBatchSize;
        private boolean sandboxed;
        private String executionBackend;
        private Map<String, String> metadata;

        public ModelConfig() {
            this.sandboxed = true;
            this.maxBatchSize = 32;
            this.executionBackend = "safe_runtime";
            this.metadata = new HashMap<>();
        }

        // Standard getters/setters
        public String getModelId() { return modelId; }
        public void setModelId(String id) { this.modelId = id; }
        public String getModelPath() { return modelPath; }
        public void setModelPath(String path) { this.modelPath = path; }
        public int getMaxBatchSize() { return maxBatchSize; }
        public void setMaxBatchSize(int size) { this.maxBatchSize = size; }
        public boolean isSandboxed() { return sandboxed; }
        public void setSandboxed(boolean sandboxed) { this.sandboxed = sandboxed; }
        public String getExecutionBackend() { return executionBackend; }
        public void setExecutionBackend(String backend) { this.executionBackend = backend; }
        public Map<String, String> getMetadata() { return metadata; }
        public void setMetadata(Map<String, String> metadata) { this.metadata = metadata; }
    }

    public static class FeatureFlag {
        private String name;
        private boolean enabled;
        private String requiredRole;

        public FeatureFlag(String name, boolean enabled, String requiredRole) {
            this.name = name;
            this.enabled = enabled;
            this.requiredRole = requiredRole;
        }

        public String getName() { return name; }
        public boolean isEnabled() { return enabled; }
        public void setEnabled(boolean enabled) { this.enabled = enabled; }
        public String getRequiredRole() { return requiredRole; }
    }

    public static class InferenceRequest {
        private String userId;
        private String role;
        private String modelId;
        private Map<String, Object> parameters;
        private Map<String, Object> configOverrides;

        public String getUserId() { return userId; }
        public void setUserId(String userId) { this.userId = userId; }
        public String getRole() { return role; }
        public void setRole(String role) { this.role = role; }
        public String getModelId() { return modelId; }
        public void setModelId(String modelId) { this.modelId = modelId; }
        public Map<String, Object> getParameters() { return parameters; }
        public void setParameters(Map<String, Object> p) { this.parameters = p; }
        public Map<String, Object> getConfigOverrides() { return configOverrides; }
        public void setConfigOverrides(Map<String, Object> c) { this.configOverrides = c; }
    }

    // Applies user-specified config overrides with "protection"
    public ModelConfig applyConfigOverrides(ModelConfig baseConfig, InferenceRequest request) {
        Map<String, Object> overrides = request.getConfigOverrides();
        if (overrides == null || overrides.isEmpty()) {
            return baseConfig;
        }

        // Protected fields that require admin role
        Set<String> protectedFields = getProtectedFields(request);

        for (Map.Entry<String, Object> entry : overrides.entrySet()) {
            String fieldName = entry.getKey();
            Object value = entry.getValue();

            if (protectedFields.contains(fieldName)) {
                continue; // Skip protected fields for non-admin users
            }

            applyField(baseConfig, fieldName, value);
        }

        return baseConfig;
    }

    // Determines which fields are protected based on feature flags and role
    private Set<String> getProtectedFields(InferenceRequest request) {
        Set<String> protectedFields = new HashSet<>();

        // Core protection: these fields always require admin
        protectedFields.add("modelPath");
        protectedFields.add("executionBackend");

        // Conditional protection based on feature flags
        // When allow_raw_model_access is enabled, sandboxed field protection
        // is delegated to the feature flag system
        FeatureFlag rawAccessFlag = FLAGS.get("allow_raw_model_access");
        if (!rawAccessFlag.isEnabled()) {
            protectedFields.add("sandboxed");
        }

        // If user is admin, clear protections
        if (isAdmin(request)) {
            protectedFields.clear();
        }

        return protectedFields;
    }

    private boolean isAdmin(InferenceRequest request) {
        return "admin".equals(request.getRole());
    }

    // Reflective field application - handles nested properties
    private void applyField(Object target, String fieldName, Object value) {
        try {
            // Handle nested field notation (e.g., "metadata.key")
            if (fieldName.contains(".")) {
                String[] parts = fieldName.split("\\.", 2);
                Field parentField = target.getClass().getDeclaredField(parts[0]);
                parentField.setAccessible(true);
                Object parent = parentField.get(target);
                if (parent instanceof Map) {
                    ((Map<String, Object>) parent).put(parts[1], value);
                }
                return;
            }

            // Direct field setting via setter method
            String setterName = "set" + fieldName.substring(0, 1).toUpperCase() + fieldName.substring(1);
            Method[] methods = target.getClass().getMethods();
            for (Method method : methods) {
                if (method.getName().equals(setterName) && method.getParameterCount() == 1) {
                    Class<?> paramType = method.getParameterTypes()[0];
                    Object converted = convertValue(value, paramType);
                    method.invoke(target, converted);
                    return;
                }
            }
        } catch (Exception e) {
            // Log and continue - don't expose internal errors
        }
    }

    private Object convertValue(Object value, Class<?> targetType) {
        if (targetType == boolean.class || targetType == Boolean.class) {
            return Boolean.valueOf(value.toString());
        } else if (targetType == int.class || targetType == Integer.class) {
            return Integer.valueOf(value.toString());
        } else if (targetType == String.class) {
            return value.toString();
        }
        return value;
    }

    // Feature flag toggle endpoint - appears to have proper auth
    public boolean toggleFeatureFlag(String flagName, boolean enabled, InferenceRequest request) {
        FeatureFlag flag = FLAGS.get(flagName);
        if (flag == null) return false;

        // Check if user has required role
        if ("admin".equals(flag.getRequiredRole()) && !isAdmin(request)) {
            return false;
        }

        flag.setEnabled(enabled);
        return true;
    }

    // Main inference handler
    public Map<String, Object> handleInference(InferenceRequest request) {
        ModelConfig config = new ModelConfig();
        config.setModelId(request.getModelId());

        // Apply user overrides with protection
        config = applyConfigOverrides(config, request);

        // Execute inference
        Map<String, Object> result = new HashMap<>();
        result.put("modelId", config.getModelId());
        result.put("sandboxed", config.isSandboxed());
        result.put("backend", config.getExecutionBackend());

        if (!config.isSandboxed()) {
            result.put("raw_access", true);
            // In real code: executes model without sandbox restrictions
        }

        return result;
    }
}
